using Seamless.Management;
using Seamless.Management.Server;

namespace Management.Tests;

[Collection("AuditStorage")]
public sealed class ReadAuditBuffer{
    private static AuditReadKey Key(string id="query"){var at=new DateTimeOffset(2026,11,4,0,0,0,TimeSpan.Zero);return new(at,at.AddMinutes(1),Guid.NewGuid(),"user","sales",id,"dll",null);}
    private static ReadAuditOptions Options(int keys=32,long bytes=1<<20)=>new(TimeSpan.FromMinutes(1),MaximumKeys:keys,MaximumBytes:bytes,MaximumBatch:4);
    [Fact]public async Task ConcurrentRecordsAreSavedInBoundedBatches(){var key=Key();var counts=new Dictionary<AuditReadKey,long>();var ids=new HashSet<Guid>();await using var buffer=new Seamless.Management.Server.ReadAuditBuffer(Options(),(id,rows,_)=>{Assert.True(ids.Add(id));Assert.InRange(rows.Length,1,4);foreach(var row in rows){counts[row.Key]=counts.GetValueOrDefault(row.Key)+row.Count;}return ValueTask.CompletedTask;},false);Parallel.For(0,10000,index=>Assert.True(buffer.Record(key with{QueryId="q"+(index%10)})));Assert.True(await buffer.FlushAsync());Assert.Equal(10000,counts.Values.Sum());Assert.Equal(10,counts.Count);Assert.Equal(0,buffer.Status().PendingBytes);Assert.Equal(10000,buffer.Status().SavedCount);}
    [Fact]public async Task NewRecordsDuringSaveDoNotChangeTheFrozenBatch(){var key=Key();var entered=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var release=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var values=new List<long>();await using var buffer=new Seamless.Management.Server.ReadAuditBuffer(Options(),async(_,rows,_)=>{values.Add(Assert.Single(rows).Count);if(values.Count==1){entered.SetResult();await release.Task;}},false);Assert.True(buffer.Record(key));var flush=buffer.FlushAsync();await entered.Task.WaitAsync(TimeSpan.FromSeconds(10));Assert.True(await Task.Run(()=>buffer.Record(key)).WaitAsync(TimeSpan.FromSeconds(10)));Assert.Equal(1,values[0]);release.SetResult();Assert.True(await flush);Assert.Equal(new long[]{1},values);Assert.Equal(1,buffer.Status().PendingKeys);Assert.True(await buffer.FlushAsync());Assert.Equal(new long[]{1,1},values);Assert.Equal(2,buffer.Status().SavedCount);}
    [Fact]public async Task FullBufferDropsNewKeysWithoutWaitingForTheBlockedSave(){var entered=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var release=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);await using var buffer=new Seamless.Management.Server.ReadAuditBuffer(Options(1),async(_,_,_)=>{entered.SetResult();await release.Task;},false);Assert.True(buffer.Record(Key()));var flush=buffer.FlushAsync();await entered.Task.WaitAsync(TimeSpan.FromSeconds(10));Assert.False(await Task.Run(()=>buffer.Record(Key("other"))).WaitAsync(TimeSpan.FromSeconds(10)));var state=buffer.Status();Assert.Equal(1,state.PendingKeys);Assert.Equal(1,state.DroppedCount);Assert.True(state.PendingBytes>0);release.SetResult();await flush;Assert.Equal(1,buffer.Status().SavedCount);}
    [Fact]public async Task LostSaveResponseRetriesTheSameBatchWithoutDoubleCounting(){var root=Path.Combine(Environment.GetEnvironmentVariable("SEAMLESS_MANAGEMENT_TEST_ROOT")!,Guid.NewGuid().ToString("N"));using var store=ManagementStore.Initialize(root,"admin","TestPassword-123");var key=Key();Guid? first=null;var calls=0;await using var buffer=new Seamless.Management.Server.ReadAuditBuffer(Options(),(id,rows,_)=>{calls++;first??=id;Assert.Equal(first.Value,id);store.ApplyReadSummaryBatch(id,rows);if(calls==1){throw new IOException("private path");}return ValueTask.CompletedTask;},false);buffer.Record(key);Assert.False(await buffer.FlushAsync());Assert.Equal(1,buffer.Status().PendingKeys);Assert.Equal("SaveFailed",buffer.Status().ErrorCode);Assert.True(await buffer.FlushAsync());Assert.Equal(1,store.ReadSummary(key)!.Count);Assert.Equal(1,buffer.Status().SavedCount);Assert.Equal(1,buffer.Status().SaveFailures);Assert.Null(buffer.Status().ErrorCode);}
    [Fact]public async Task ByteLimitAndFailureOnShutdownSeparateKnownLossFromUnknownOutcome(){var buffer=new Seamless.Management.Server.ReadAuditBuffer(Options(bytes:1024),(_,_,_)=>throw new IOException("SECRET"),false);Assert.False(buffer.Record(Key() with{SubjectId=new string('x',1000)}));Assert.True(buffer.Record(Key()));await buffer.DisposeAsync();var state=buffer.Status();Assert.True(state.Closed);Assert.Equal(1,state.DroppedCount);Assert.Equal(1,state.UnconfirmedCount);Assert.Equal(0,state.PendingKeys);Assert.Equal(0,state.PendingBytes);Assert.Equal("SaveFailed",state.ErrorCode);Assert.False(buffer.Record(Key()));}
    [Fact]public async Task ConcurrentDisposeWaitsForTheSameSave(){var entered=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var release=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var buffer=new Seamless.Management.Server.ReadAuditBuffer(Options(),async(_,_,_)=>{entered.SetResult();await release.Task;},false);buffer.Record(Key());var first=buffer.DisposeAsync().AsTask();await entered.Task.WaitAsync(TimeSpan.FromSeconds(10));var second=buffer.DisposeAsync().AsTask();try{Assert.False(second.IsCompleted);}finally{release.SetResult();await Task.WhenAll(first,second);}Assert.Equal(1,buffer.Status().SavedCount);}
    [Fact]public async Task DefaultFiveSecondWorkerSavesWithoutManualFlush(){var saved=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);await using var buffer=new Seamless.Management.Server.ReadAuditBuffer(new ReadAuditOptions(),(_,_,_)=>{saved.TrySetResult();return ValueTask.CompletedTask;});buffer.Record(Key());await saved.Task.WaitAsync(TimeSpan.FromSeconds(15));}
    [Fact]public async Task RepeatedNewHotKeyDoesNotStarveExistingKeysOrRepeatInOneCycle(){var key=Key("hot");var values=new List<string>();Seamless.Management.Server.ReadAuditBuffer? buffer=null;await using var owned=buffer=new(Options(8) with{MaximumBatch=1},(_,rows,_)=>{var item=Assert.Single(rows);values.Add(item.Key.QueryId);if(item.Key.QueryId=="hot"){buffer!.Record(key);}return ValueTask.CompletedTask;},false);buffer.Record(key);buffer.Record(key with{QueryId="cold-a"});buffer.Record(key with{QueryId="cold-b"});Assert.True(await buffer.FlushAsync());Assert.Equal(3,values.Count);Assert.Contains("cold-a",values);Assert.Contains("cold-b",values);Assert.Equal(1,buffer.Status().PendingKeys);}
}
